+            assertNull(CampaignPushStore.peekPendingRequestId(context, "userA", "cA"))
+        } finally {
+            CampaignPushStore.clearPendingRequestId(context, "userA", "cA")
+            vm.viewModelScope.cancel()
+            Dispatchers.resetMain()
+        }
+    }
